<script setup>
import { onMounted } from "vue";
import { RouterLink, useRoute, useRouter } from "vue-router";
import { useGrievanceStore } from "@/stores/grievanceStore";
const route = useRoute(); const router = useRouter(); const store = useGrievanceStore();
const statuses = { submitted: "Soumise", rejected: "Rejetée", in_progress: "En cours", processed: "Traitée" };
const statusLabel = (value) => statuses[value] || value;
const date = (value) => value ? new Intl.DateTimeFormat("fr-FR", { dateStyle: "medium", timeStyle: "short" }).format(new Date(value)) : "—";
onMounted(() => store.fetchGrievance(route.params.id));
async function removeDocument(document) { if (window.confirm(`Supprimer le document « ${document.name} » ?`)) await store.removeDocument(route.params.id, document.id); }
async function remove() { if (window.confirm("Supprimer définitivement cette doléance ?")) { await store.removeGrievance(route.params.id); router.push({ name: "admin-grievances" }); } }
</script>
<template>
  <section class="detail-page"><RouterLink :to="{ name: 'admin-grievances' }" class="back-link">← Retour aux doléances</RouterLink><div v-if="store.loading && !store.current" class="state">Chargement…</div><template v-else-if="store.current"><div class="detail-heading"><div><p class="eyebrow">Administration / Doléances / #{{ store.current.id }}</p><h2>{{ store.current.title }}</h2><p class="description">Suivi complet de la demande et de ses changements.</p></div><div class="heading-actions"><RouterLink :to="{ name: 'admin-grievance-edit', params: { id: store.current.id } }" class="edit-button">Modifier</RouterLink><button class="delete-button" type="button" @click="remove">Supprimer</button></div></div><div class="summary-grid"><article><small>État actuel</small><strong class="status-pill" :class="store.current.status">{{ statusLabel(store.current.status) }}</strong></article><article><small>Secteur</small><strong>{{ store.current.sector?.name || "—" }}</strong></article><article><small>Attribution</small><strong>{{ store.current.department?.name || "Non attribuée" }}</strong></article><article><small>Échéance</small><strong>{{ date(store.current.due_at) }}</strong></article></div><div class="detail-grid"><article class="detail-card description-card"><h3>Description</h3><p>{{ store.current.description }}</p><h3 class="subheading">Dates</h3><dl><div><dt>Date de la doléance</dt><dd>{{ date(store.current.complained_at) }}</dd></div><div><dt>Date d’échéance</dt><dd>{{ date(store.current.due_at) }}</dd></div></dl></article><article class="detail-card"><h3>Documents</h3><p v-if="!store.current.documents?.length" class="muted">Aucun document joint.</p><ul v-else class="documents"><li v-for="document in store.current.documents" :key="document.id"><a :href="document.url" target="_blank" rel="noreferrer">{{ document.name }}</a><button type="button" @click="removeDocument(document)">×</button></li></ul></article><article class="detail-card"><h3>Historique des statuts</h3><ul class="timeline"><li v-for="entry in store.current.status_history" :key="entry.id"><span class="timeline-dot" /><div><strong>{{ statusLabel(entry.status) }}</strong><small>{{ date(entry.changed_at) }} · {{ entry.changed_by?.name || "Utilisateur supprimé" }}</small></div></li></ul></article><article class="detail-card"><h3>Historique des attributions</h3><ul class="timeline"><li v-for="entry in store.current.assignment_history" :key="entry.id"><span class="timeline-dot purple" /><div><strong>{{ entry.department?.name || "Non attribuée" }}</strong><small>{{ date(entry.changed_at) }} · {{ entry.changed_by?.name || "Utilisateur supprimé" }}</small></div></li></ul></article></div></template><p v-else class="state">Cette doléance est introuvable.</p></section>
</template>
